import sys

def count_neighbors(grid, r, c):
    rows = len(grid)
    cols = len(grid[0])
    count = 0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '#':
                count += 1
    return count

def next_generation(grid):
    rows = len(grid)
    cols = len(grid[0])
    new_grid = []
    for r in range(rows):
        row_chars = []
        for c in range(cols):
            count = count_neighbors(grid, r, c)
            if grid[r][c] == '#':
                if count == 2 or count == 3:
                    row_chars.append('#')
                else:
                    row_chars.append('.')
            else:
                if count == 3:
                    row_chars.append('#')
                else:
                    row_chars.append('.')
        new_grid.append(''.join(row_chars))
    return new_grid

def main():
    if len(sys.argv) != 3:
        print("Uso: python3 vida.py <archivo> <generaciones>", file=sys.stderr)
        sys.exit(1)

    archivo = sys.argv[1]
    try:
        n = int(sys.argv[2])
        if n < 0:
            raise ValueError("N no puede ser negativo")
    except ValueError as e:
        print(f"Error: N debe ser un entero no negativo: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(archivo, 'r', encoding='utf-8') as f:
            lineas = f.read().splitlines()
    except FileNotFoundError:
        print(f"Error: no se encuentra el archivo {archivo}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Error leyendo archivo: {e}", file=sys.stderr)
        sys.exit(1)

    if not lineas:
        print("Error: archivo vacío", file=sys.stderr)
        sys.exit(1)

    ancho = len(lineas[0])
    for linea in lineas:
        if len(linea) != ancho:
            print("Error: filas de distinta longitud", file=sys.stderr)
            sys.exit(1)

    grid = lineas
    for _ in range(n):
        grid = next_generation(grid)

    print('\n'.join(grid))

if __name__ == "__main__":
    main()
